{
  "items": [
    {
      "name": "Cardinal.mk_mul_le",
      "module_name": "Mathlib.Algebra.Group.Pointwise.Set.Card",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} [inst : Mul M] {s t : Set M}, Cardinal.mk ↑(s * t) ≤ Cardinal.mk ↑s * Cardinal.mk ↑t"
    },
    {
      "name": "Set.encard_prod",
      "module_name": "Mathlib.Data.Set.Card",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {s : Set α} {t : Set β}, (s ×ˢ t).encard = s.encard * t.encard"
    },
    {
      "name": "Finsupp.card_pi",
      "module_name": "Mathlib.Data.Finset.Finsupp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : Zero α] (f : ι →₀ Finset α), f.pi.card = f.prod fun i => ↑(f i).card"
    },
    {
      "name": "Cardinal.mk_setProd",
      "module_name": "Mathlib.SetTheory.Cardinal.Basic",
      "kind": "theorem",
      "type": "∀ {α β : Type u} (s : Set α) (t : Set β), Cardinal.mk ↑(s ×ˢ t) = Cardinal.mk ↑s * Cardinal.mk ↑t"
    },
    {
      "name": "Finset.card_mul_le",
      "module_name": "Mathlib.Algebra.Group.Pointwise.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : DecidableEq α] [inst_1 : Mul α] {s t : Finset α}, (s * t).card ≤ s.card * t.card"
    },
    {
      "name": "Set.encard_pi_eq_prod_encard",
      "module_name": "Mathlib.Data.Set.Card",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [h : Fintype α] {ι : α → Type u_3} {s : (i : α) → Set (ι i)},\n  (Set.univ.pi s).encard = ∏ i, (s i).encard"
    },
    {
      "name": "Set.natCard_mul_le",
      "module_name": "Mathlib.Algebra.Group.Pointwise.Set.Card",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} [inst : Mul M] {s t : Set M} [IsCancelMul M], Nat.card ↑(s * t) ≤ Nat.card ↑s * Nat.card ↑t"
    },
    {
      "name": "Multiset.card_product",
      "module_name": "Mathlib.Data.Multiset.Bind",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type v} (s : Multiset α) (t : Multiset β), (s ×ˢ t).card = s.card * t.card"
    }
  ]
}
